/v1/boosts.post:
import { PromotionsPostBoostsRequest, RidgelinePromotions } from 'ridgeline-promotions';

(async () => {
  const ridgelinePromotions = new RidgelinePromotions({
	token: 'YOUR_TOKEN',
});

  const products = "sportsbook"

  const promotionsPostBoostsRequest: PromotionsPostBoostsRequest = {	
    name: "name",
    marketId: "market_id",
    profitBoostPct: 8,
    rewardsBackPct: 2,
    products: [products]
  };

  const data = await ridgelinePromotions.promotions.promotionsPostBoosts(promotionsPostBoostsRequest);

  console.log(data);
})();

